// Mibot stand-in for @deepseek-ai/dsh-tools (host kit 3).
// Plugins import authoring helpers from this package; Mibot's host provides the
// `tools` service itself (host.mjs ToolsService), so everything here is plain
// data: defineTool returns the tool object unchanged and ctx.tools.register()
// takes it as is.
export const name = 'dsh-tools'
export const MIBOT_STAND_IN = true
export const RISKS = Object.freeze(['read', 'write', 'external'])

/** defineTool({ name, description, parameters, risk?, annotations?, output?, execute }) → the same object. */
export function defineTool(def) {
  if (!def || typeof def !== 'object') throw new TypeError('defineTool needs a tool definition object')
  return def
}

/** Several at once. */
export function defineTools(defs) { return Array.isArray(defs) ? defs.map(defineTool) : defineTool(defs) }

/** Text / image result helpers (the host also accepts plain strings and objects). */
export const text = (t) => ({ type: 'text', text: String(t ?? '') })
export const image = (path) => ({ type: 'image', path: String(path) })
export function toolResult(content, extra = {}) { return { content: Array.isArray(content) ? content : [content], ...extra } }

export default { name, defineTool, defineTools, text, image, toolResult, RISKS }
